# How often each target actually turns up on a normal thrift / bins / yard-sale
# run — Common, Occasional or Rare. A sourcing estimate like Typical Cost, used
# to keep the "Everyday thrift finds" shelf to things you'll really see.
COMMON = 'carhartt-jacket the-north-face-jacket the-north-face-fleece-vest levi-s-denim-jacket nike-windbreaker adidas-track-jacket columbia-fleece-jacket champion-hoodie vintage-flannel-shirt ralph-lauren-polo levi-s-501-jeans wrangler-jeans dickies-pants lululemon-leggings calvin-klein-jeans new-balance-sneakers vans-old-skool ugg-boots vans-shoes stanley-tumbler yeti-tumbler canon-powershot-elph-digital-camera 35mm-point-and-shoot-film-camera ti-84-plus-ce-graphing-calculator sony-discman-portable-cd-player logitech-harmony-remote xbox-wireless-controller dewalt-20v-battery-charger vintage-pyrex-bowl corningware-blue-cornflower lego-bulk-lot squishmallows-plush titleist-pro-v1-used-golf-balls classic-rock-vinyl-lp complete-series-dvd-box-set stephen-king-first-edition-hardcover vintage-cookbook kindle-paperwhite jbl-flip-bluetooth-speaker nintendo-ds-lite-console ryobi-18v-one-tool irobot-roomba singer-sewing-machine kate-spade-purse michael-kors-handbag birkenstock-sandals cole-haan-loafers'.split()
RARE = 'burberry-scarf sony-wh-1000xm4-headphones nintendo-switch-console focusrite-scarlett-audio-interface shure-sm58-microphone akai-mpk-mini-midi-controller mackie-mixer numark-dj-controller boss-guitar-pedal electro-harmonix-guitar-pedal bosch-laser-measure autel-obd2-scanner le-creuset-dutch-oven vitamix-blender-base hot-wheels-redline vintage-advertising-tin-sign scotty-cameron-putter bowflex-selecttech-dumbbells elgato-stream-deck raspberry-pi-board milwaukee-packout-tool-box barbour-jacket arc-teryx-jacket'.split()


def thrift_frequency(row_id, explicit):
    if explicit:
        return explicit
    if row_id in COMMON:
        return 'Common'
    if row_id in RARE:
        return 'Rare'
    return 'Occasional'


def slug(term):
    return re.sub(r'^-+|-+$', '', re.sub(r'[^a-z0-9]+', '-', term.lower()))


def rows():
    out = []
    for r in ROWS:
        cost = r.get('cost') or (None, None)
        out.append({
            'opportunityId': slug(r['t']),
            'searchTerm': r['t'],
            'ebayQuery': r.get('eb', ''),
            'poshmarkQuery': r.get('pm', ''),
            'brand': r.get('brand', ''),
            'model': r.get('model', ''),
            'category': r['cat'],
            'subcategory': r.get('sub', ''),
            'keywords': r.get('kw', ''),
            'shippingClass': r.get('ship', ''),
            'testingRisk': r.get('test', ''),
            'counterfeitRisk': r.get('fake', ''),
            'shippingDifficulty': SHIP_DIFFICULTY.get(r.get('ship', ''), ''),
            'fragility': r.get('frag', ''),
            'returnRisk': r.get('ret', ''),
            'knowledgeLevel': r.get('know', ''),
            'conditionRequirement': r.get('req', ''),
            'typicalCostLow': cost[0] if cost[0] is not None else '',
            'typicalCostHigh': cost[1] if cost[1] is not None else '',
            'sourcingLocations': r.get('loc', ''),
            'inspectionNotes': '\n'.join(r.get('chk', [])),
            'recognitionNotes': '\n'.join(r.get('see', [])),
            'platformNotes': r.get('plat', ''),
            'active': 'Y',
            'thriftFrequency': thrift_frequency(slug(r['t']), r.get('freq')),
        })
    return out


if __name__ == '__main__':
    data = rows()
    ids = [d['opportunityId'] for d in data]
    dupes = {i for i in ids if ids.count(i) > 1}
    if dupes:
        sys.exit(f'duplicate opportunity ids: {dupes}')
    json.dump(data, sys.stdout, indent=1)
